(function() {
    'use strict';

    class PetrolStandOffAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Petrol Station Stand-Off';
            this.version = '1.1.0';
            this.ROUND_BRIEFINGS = [
                'You and Petrolia face each other at the motorway junction. Will you hold the price at \u00a31.50 per litre, or undercut to \u00a31.40 to steal all the customers? Petrolia has not revealed its hand yet\u2026',
                'The price war is on! Last round showed what happens when rivalry heats up. Both stations are watching each other closely. Will you cooperate or compete?',
                'Petrolia has adopted a tit-for-tat strategy: it will mirror your previous move. Cooperation could benefit you both \u2014 but can you trust it long-term?',
                'The temptation to defect is strong. One round of undercutting yields \u00a3750\u2026 but what happens when your rival retaliates next time?',
                'A secret meeting is possible. You can send a message to Petrolia proposing a price-fixing agreement \u2014 but the CMA is watching. Getting caught means a \u00a31,500 fine that wipes out your run.',
                'A discount brand \u2014 ValueFuel \u2014 has opened nearby! With three stations competing, the market is tighter. Tacit collusion just got much harder. Payoffs have changed \u2014 check the matrix.'
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 0,
                    rivalCash: 0,
                    playerChoices: [],
                    rivalChoices: [],
                    profitHistory: [],
                    rivalProfitHistory: [],
                    cmaFined: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    priceChoice: '',
                    cartelMessage: false
                };
            }
            this._setupChoiceButtons();
            this._updateBriefing(state);
        }

        _setupChoiceButtons() {
            var holdBtn = document.getElementById('holdBtn');
            var undercutBtn = document.getElementById('undercutBtn');
            var choiceInput = document.getElementById('priceChoiceInput');
            var selectedDisplay = document.getElementById('selectedChoiceDisplay');
            var selectedText = document.getElementById('selectedChoiceText');
            if (holdBtn) {
                holdBtn.addEventListener('click', function() {
                    if (choiceInput) choiceInput.value = 'hold';
                    holdBtn.classList.add('petrol-sim-selected');
                    if (undercutBtn) undercutBtn.classList.remove('petrol-sim-selected');
                    if (selectedDisplay) selectedDisplay.style.display = 'block';
                    if (selectedText) selectedText.textContent = '\u00a31.50 (Hold)';
                });
            }
            if (undercutBtn) {
                undercutBtn.addEventListener('click', function() {
                    if (choiceInput) choiceInput.value = 'undercut';
                    undercutBtn.classList.add('petrol-sim-selected');
                    if (holdBtn) holdBtn.classList.remove('petrol-sim-selected');
                    if (selectedDisplay) selectedDisplay.style.display = 'block';
                    if (selectedText) selectedText.textContent = '\u00a31.40 (Undercut)';
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUND_BRIEFINGS.length - 1);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this.ROUND_BRIEFINGS[idx];

            var cartelOption = document.getElementById('cartelOption');
            if (cartelOption) cartelOption.style.display = ((state.currentPeriod || 1) === 5) ? 'block' : 'none';

            var isRound6 = (state.currentPeriod || 1) >= 6;
            var cellHH = document.getElementById('cell_hh');
            var cellHU = document.getElementById('cell_hu');
            var cellUH = document.getElementById('cell_uh');
            var cellUU = document.getElementById('cell_uu');
            if (cellHH) cellHH.textContent = isRound6 ? '\u00a3300 / \u00a3300' : '\u00a3500 / \u00a3500';
            if (cellHU) cellHU.textContent = isRound6 ? '\u00a30 / \u00a3450' : '\u00a30 / \u00a3750';
            if (cellUH) cellUH.textContent = isRound6 ? '\u00a3450 / \u00a30' : '\u00a3750 / \u00a30';
            if (cellUU) cellUU.textContent = isRound6 ? '\u00a3100 / \u00a3100' : '\u00a3200 / \u00a3200';

            var vfIndicator = document.getElementById('valueFuelIndicator');
            if (vfIndicator) vfIndicator.style.display = isRound6 ? 'block' : 'none';

            var choiceInput = document.getElementById('priceChoiceInput');
            if (choiceInput) choiceInput.value = '';
            var holdBtn = document.getElementById('holdBtn');
            var undercutBtn = document.getElementById('undercutBtn');
            if (holdBtn) holdBtn.classList.remove('petrol-sim-selected');
            if (undercutBtn) undercutBtn.classList.remove('petrol-sim-selected');
            var selectedDisplay = document.getElementById('selectedChoiceDisplay');
            if (selectedDisplay) selectedDisplay.style.display = 'none';
            var cartelCheck = document.getElementById('cartelMessage');
            if (cartelCheck) cartelCheck.checked = false;

            var cells = document.querySelectorAll('.petrol-sim-matrix-table td');
            cells.forEach(function(c) { c.classList.remove('petrol-sim-cell-active'); });

            var cmaAlarm = document.getElementById('cmaAlarm');
            if (cmaAlarm) cmaAlarm.style.display = 'none';
        }

        validateDecisions(decisions) {
            // Do NOT call _updateBriefing() here. It resets priceChoiceInput.value to ''
            // (and clears the button selection), so calling it *before* reading the choice
            // below wiped the player's selection and made every submit fail the
            // 'choice_warning' guard -> the game was unsubmittable. The panel for the next
            // round is refreshed by initialize() and by the deferred advance in
            // calculateResults(), so this call was both redundant and destructive.
            var choiceInput = document.getElementById('priceChoiceInput');
            if (choiceInput) decisions.priceChoice = choiceInput.value;

            var cartelCheck = document.getElementById('cartelMessage');
            if (cartelCheck) decisions.cartelMessage = cartelCheck.checked;

            if (!decisions.priceChoice || (decisions.priceChoice !== 'hold' && decisions.priceChoice !== 'undercut')) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        _getAiChoice(state) {
            var round = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            if (round === 1) return 'hold';
            if (round === 2) return 'undercut';
            if (round === 5 && d.cartelMessage) return 'hold';
            if (ds.playerChoices.length > 0) {
                return ds.playerChoices[ds.playerChoices.length - 1];
            }
            return 'hold';
        }

        _getAiSpeech(round, aiChoice, state) {
            if (round === 1) return window.mySimulation.t('ai_speech_r1');
            if (round === 2) return window.mySimulation.t('ai_speech_r2');
            if (round === 5 && state.decisions.cartelMessage) return window.mySimulation.t('ai_speech_cartel');
            if (round === 6) return window.mySimulation.t('ai_speech_r6');
            var prevChoice = state.domainState.playerChoices.length > 0 ? state.domainState.playerChoices[state.domainState.playerChoices.length - 1] : 'hold';
            if (prevChoice === 'hold') return window.mySimulation.t('ai_speech_tft_coop');
            return window.mySimulation.t('ai_speech_tft_defect');
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var aiChoice = this._getAiChoice(state);
            var aiSpeech = this._getAiSpeech(round, aiChoice, state);
            var isRound6 = (round === 6);

            var playerProfit = 0;
            var rivalProfit = 0;

            if (d.priceChoice === 'hold' && aiChoice === 'hold') {
                playerProfit = isRound6 ? 300 : 500;
                rivalProfit = isRound6 ? 300 : 500;
            } else if (d.priceChoice === 'hold' && aiChoice === 'undercut') {
                playerProfit = 0;
                rivalProfit = isRound6 ? 450 : 750;
            } else if (d.priceChoice === 'undercut' && aiChoice === 'hold') {
                playerProfit = isRound6 ? 450 : 750;
                rivalProfit = 0;
            } else {
                playerProfit = isRound6 ? 100 : 200;
                rivalProfit = isRound6 ? 100 : 200;
            }

            var cmaFine = 0;
            if (round === 5 && d.cartelMessage) {
                var caught = Math.random() < 0.4;
                if (caught) {
                    cmaFine = 1500;
                    playerProfit = playerProfit - cmaFine;
                    ds.cmaFined = true;
                }
            }

            ds.cash += playerProfit;
            ds.rivalCash += rivalProfit;
            ds.playerChoices.push(d.priceChoice);
            ds.rivalChoices.push(aiChoice);
            ds.profitHistory.push(playerProfit);
            ds.rivalProfitHistory.push(rivalProfit);

            var pChoice = d.priceChoice;
            var self = this;
            setTimeout(function() {
                var playerTag = document.getElementById('playerPriceTag');
                if (playerTag) playerTag.textContent = pChoice === 'hold' ? '\u00a31.50' : '\u00a31.40';
                var rivalTag = document.getElementById('rivalPriceTag');
                if (rivalTag) rivalTag.textContent = aiChoice === 'hold' ? '\u00a31.50' : '\u00a31.40';

                var speechEl = document.getElementById('rivalSpeech');
                if (speechEl) speechEl.textContent = aiSpeech;

                var cells = document.querySelectorAll('.petrol-sim-matrix-table td');
                cells.forEach(function(c) { c.classList.remove('petrol-sim-cell-active'); });
                var cellId = 'cell_' + (pChoice === 'hold' ? 'h' : 'u') + (aiChoice === 'hold' ? 'h' : 'u');
                var activeCell = document.getElementById(cellId);
                if (activeCell) activeCell.classList.add('petrol-sim-cell-active');

                if (cmaFine > 0) {
                    var cmaAlarm = document.getElementById('cmaAlarm');
                    if (cmaAlarm) cmaAlarm.style.display = 'block';
                }
            }, 300);

            // FIX off-by-one: use the pre-increment round captured above (round = N), not
            // state.currentPeriod, which the framework increments to N+1 the instant this
            // function returns -> the old code advanced the briefing to N+2 (after Round 1
            // it showed Round 3's briefing/payoff-matrix and, entering Round 5, hid the
            // cartel option). round + 1 = N+1 is the correct next round. Kept deferred 1500ms
            // to preserve the result reveal before the next briefing loads; skipped after the
            // final round.
            if (round < this.ROUND_BRIEFINGS.length) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: round + 1, domainState: ds, decisions: d });
                }, 1500);
            }

            return {
                period: round,
                playerChoice: d.priceChoice,
                aiChoice: aiChoice,
                playerProfit: playerProfit,
                rivalProfit: rivalProfit,
                cmaFine: cmaFine,
                cash: ds.cash,
                rivalCash: ds.rivalCash
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return '\u00a3' + Math.round(v).toLocaleString(); });
            uiManager.bind('rivalCashDisplay', 'domainState.rivalCash', function(v) { return '\u00a3' + Math.round(v).toLocaleString(); });
            uiManager.bind('roundProfitDisplay', 'results.playerProfit', function(v) {
                if (v === undefined || v === null) return '-';
                var sign = v >= 0 ? '\u00a3' : '-\u00a3';
                return sign + Math.abs(Math.round(v)).toLocaleString();
            });
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Your Profit (\u00a3)',
                                data: [],
                                backgroundColor: 'rgba(0,255,136,0.7)',
                                borderColor: '#00ff88',
                                borderWidth: 1
                            },
                            {
                                label: 'Rival Profit (\u00a3)',
                                data: [],
                                backgroundColor: 'rgba(255,71,87,0.7)',
                                borderColor: '#ff4757',
                                borderWidth: 1
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Profit Per Round', color: '#a0aec0' },
                            legend: { labels: { color: '#a0aec0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#a0aec0' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#a0aec0' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.profitHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.profitHistory },
                        { data: state.domainState.rivalProfitHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? (r.results.playerProfit || 0) : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var coopMax = 2800;
            var ratio = totalProfit / coopMax;
            var stars = 0;
            if (ratio >= 0.9) stars = 3;
            else if (ratio >= 0.7) stars = 2;
            else if (ratio >= 0.5) stars = 1;

            var performance = 'Needs Improvement';
            if (stars >= 3) performance = 'Excellent';
            else if (stars >= 2) performance = 'Good';
            else if (stars >= 1) performance = 'Fair';

            var insights = [];
            if (ratio >= 0.9) {
                insights.push('Outstanding cooperation strategy. You maximised joint profits while protecting your position.');
            } else if (ratio >= 0.7) {
                insights.push('Solid understanding of strategic interdependence. Consistent cooperation paid off.');
            } else if (ratio >= 0.5) {
                insights.push('Price wars cost both sides. Tit-for-tat strategies reward cooperation over time.');
            } else {
                insights.push('Frequent undercutting led to mutually destructive outcomes. In repeated games, cooperation can be the dominant long-run strategy.');
            }

            return {
                totalProfit: totalProfit,
                stars: stars,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cmaFine > 0) return window.mySimulation.t('hint_cma');
            if (results.playerProfit <= 0) return window.mySimulation.t('hint_loss');
            if (results.playerChoice === 'hold' && results.aiChoice === 'hold') return window.mySimulation.t('hint_coop');
            if (results.playerChoice === 'undercut' && results.aiChoice === 'undercut') return window.mySimulation.t('hint_war');
            if (results.playerProfit === 750 || results.playerProfit === 450) return window.mySimulation.t('hint_defect_win');
            return null;
        }

